fn render_synopsis_arg(arg: &Arg) -> Vec<Inline> {
    if arg.is_positional() {
        let value = arg
            .get_value_names()
            .map(|v| v.join(" "))
            .unwrap_or_else(|| arg.get_id().as_str().to_owned());
        return vec![italic(value)];
