fn fish_quote(s: &str) -> std::borrow::Cow<'_, str> {
    if !fish_needs_quoting(s) {
        return std::borrow::Cow::Borrowed(s);
    }
    let mut out = String::with_capacity(s.len() + 2);
    out.push('\'');
    for c in s.chars() {
        match c {
            '\\' => out.push_str(r"\\"),
            '\'' => out.push_str(r"\'"),
            _ => out.push(c),
        }
    }
    out.push('\'');
    std::borrow::Cow::Owned(out)
}

